<?php require __DIR__.'/inc/core.php';require_once __DIR__.'/inc/quote-richtext.php';auth();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');$id=max(0,(int)($_GET['id']??0));if(!$id){http_response_code(400);echo json_encode(['error'=>'Geçersiz şablon']);exit;}try{$s=db()->prepare('SELECT transport_process,service_scope,payment_terms,delivery_time,additional_terms FROM moving_content_templates WHERE id=? AND active=1');$s->execute([$id]);$row=$s->fetch();if(!$row){http_response_code(404);echo json_encode(['error'=>'Şablon bulunamadı']);exit;}if(!empty($row['transport_process']))$row['service_scope']=ekRichDisplay($row['service_scope']??'').'<div>'.ekRichDisplay($row['transport_process']).'</div>';unset($row['transport_process']);foreach($row as $key=>$value)$row[$key]=ekRichDisplay($value);echo json_encode(['fields'=>$row],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(500);echo json_encode(['error'=>'Şablon yüklenemedi']);}